export interface Gemma4PromptMatrixSummary {
  kind: "gemma4-ui-prompt-matrix";
  schemaVersion: 1;
  summary: { prompts: number; promptsEqual: number; promptAgreementRate: number; comparedTokenSteps: number; equalTokenSteps: number; tokenAgreementRate: number; firstDivergentPrompt: number | null; fallbackPrompts: number; fallbackRate: number; correctionPrompts: number; fallbackImprovedPrompts: number; fallbackWorsenedPrompts: number; fallbackChangedStillDivergentPrompts: number; verificationEarlyExitPrompts: number; verificationDecoderSteps: number; verificationDecoderStepsAvoided: number; verificationHeadPositionsComputed: number; verificationHeadPositionsAvoided: number; verificationPrefillAheadPrompts: number; verificationPrefillAheadSeconds: number; verificationPrefillOverlapSeconds: number; verificationPrefillWaitSeconds: number; verificationSessionCacheHitPrompts: number; verificationPrefixTokensReused: number; verificationPrefillTokensComputed: number; baselineSeconds: number; directSeconds: number; baselineTokensPerSecond: number; directTokensPerSecond: number; directVsBaselineThroughputRatio: number; meanFirstTokenWallSeconds: number | null; directRootDivergences: number; meanTopKOverlapRate: number | null; maxBaselineArgmaxLogitAbsError: number | null };
  cases: Array<{ prompt: string; tokensEqual: boolean; firstDivergentStep: number | null; baselineTokenIds: number[]; directTokenIds: number[]; baselineSeconds: number; directSeconds: number; speedup: number; firstTokenWallSeconds: number | null; selectedBackend: string; fallbackTriggered: boolean; correctionTriggered: boolean; fallbackOutcome: string | null; verificationEarlyExitStep: number | null; verificationDecoderSteps: number; verificationDecoderStepsAvoided: number; verificationHeadPositionsComputed: number; verificationHeadPositionsAvoided: number; verificationPrefillAhead: boolean; verificationPrefillAheadSeconds: number; verificationPrefillOverlapSeconds: number; verificationPrefillWaitSeconds: number; verificationSessionCacheHit: boolean; verificationPrefixTokensReused: number; verificationPrefillTokensComputed: number }>;
  reports: unknown[];
}

export function parseGemma4PromptMatrixInput(value: string): string[] {
  if (typeof value !== "string") throw new Error("Matriz de prompts deve ser texto.");
  let prompts: unknown; const trimmed = value.trim();
  if (trimmed.startsWith("[")) { try { prompts = JSON.parse(trimmed); } catch { throw new Error("JSON da matriz de prompts é inválido."); } }
  else prompts = value.split(/\r?\n/).map((prompt) => prompt.trim()).filter(Boolean);
  if (!Array.isArray(prompts) || prompts.length < 1 || prompts.length > 32 || prompts.some((prompt) => typeof prompt !== "string" || prompt.length < 1 || prompt.length > 16_384)) throw new Error("Informe entre 1 e 32 prompts válidos, um por linha ou em um array JSON.");
  return [...prompts] as string[];
}

export function summarizeGemma4PromptMatrix(reports: unknown[]): Gemma4PromptMatrixSummary {
  if (!Array.isArray(reports) || reports.length === 0) throw new Error("Matriz requer ao menos um relatório.");
  const cases: Gemma4PromptMatrixSummary["cases"] = [];
  let comparedTokenSteps = 0, equalTokenSteps = 0, baselineSeconds = 0, directSeconds = 0, promptsEqual = 0, fallbackPrompts = 0, correctionPrompts = 0, fallbackImprovedPrompts = 0, fallbackWorsenedPrompts = 0, fallbackChangedStillDivergentPrompts = 0, verificationEarlyExitPrompts = 0, verificationDecoderSteps = 0, verificationDecoderStepsAvoided = 0, verificationHeadPositionsComputed = 0, verificationHeadPositionsAvoided = 0, verificationPrefillAheadPrompts = 0, verificationPrefillAheadSeconds = 0, verificationPrefillOverlapSeconds = 0, verificationPrefillWaitSeconds = 0, verificationSessionCacheHitPrompts = 0, verificationPrefixTokensReused = 0, verificationPrefillTokensComputed = 0, directRootDivergences = 0;
  const firstTokenSeconds: number[] = [], topKOverlapRates: number[] = [], selectedLogitErrors: number[] = [];
  for (const [index, value] of reports.entries()) {
    if (typeof value !== "object" || value === null) throw new Error(`Relatório ${index} não é objeto.`);
    const report = value as Record<string, any>, direct = report.direct, performance = report.performance, execution = report.directExecutionMetrics;
    const baseline = report.baselineGeneratedTokenIds, generated = direct?.generatedTokenIds;
    if (typeof report.prompt !== "string" || !Array.isArray(baseline) || !Array.isArray(generated) || !baseline.every(Number.isSafeInteger) || !generated.every(Number.isSafeInteger) || typeof performance?.baselineSeconds !== "number" || !Number.isFinite(performance.baselineSeconds) || performance.baselineSeconds < 0 || typeof direct?.elapsedSeconds !== "number" || !Number.isFinite(direct.elapsedSeconds) || direct.elapsedSeconds < 0) throw new Error(`Relatório ${index} não contém comparação original × compilada válida.`);
    const comparedSteps = Math.max(baseline.length, generated.length); comparedTokenSteps += comparedSteps; for (let step = 0; step < comparedSteps; step += 1) if (baseline[step] === generated[step]) equalTokenSteps += 1;
    const tokensEqual = baseline.length === generated.length && baseline.every((token: number, step: number) => generated[step] === token); if (tokensEqual) promptsEqual += 1;
    baselineSeconds += performance.baselineSeconds; directSeconds += direct.elapsedSeconds; if (direct.fallbackTriggered === true) fallbackPrompts += 1; if (direct.fallbackChangedTokens === true || direct.controlCorrectionTriggered === true || Number.isSafeInteger(direct.verificationDivergenceStep)) correctionPrompts += 1; if (direct.fallbackOutcome === "improved") fallbackImprovedPrompts += 1; else if (direct.fallbackOutcome === "worsened") fallbackWorsenedPrompts += 1; else if (direct.fallbackOutcome === "changed-still-divergent") fallbackChangedStillDivergentPrompts += 1;
    const decoderSteps = Number.isSafeInteger(direct.verificationDecoderSteps) && direct.verificationDecoderSteps >= 0 ? direct.verificationDecoderSteps : 0, avoidedSteps = Number.isSafeInteger(direct.verificationDecoderStepsAvoided) && direct.verificationDecoderStepsAvoided >= 0 ? direct.verificationDecoderStepsAvoided : 0, earlyExitStep = Number.isSafeInteger(direct.verificationEarlyExitStep) && direct.verificationEarlyExitStep >= 0 ? direct.verificationEarlyExitStep : null;
    verificationDecoderSteps += decoderSteps; verificationDecoderStepsAvoided += avoidedSteps; if (earlyExitStep !== null) verificationEarlyExitPrompts += 1;
    const headPositionsComputed = Number.isSafeInteger(direct.verificationHeadPositionsComputed) && direct.verificationHeadPositionsComputed >= 0 ? direct.verificationHeadPositionsComputed : 0, headPositionsAvoided = Number.isSafeInteger(direct.verificationHeadPositionsAvoided) && direct.verificationHeadPositionsAvoided >= 0 ? direct.verificationHeadPositionsAvoided : 0;
    verificationHeadPositionsComputed += headPositionsComputed; verificationHeadPositionsAvoided += headPositionsAvoided;
    const prefillAhead = direct.verificationPrefillAhead === true, prefillAheadSeconds = finiteNonNegative(direct.verificationPrefillAheadSeconds), prefillOverlapSeconds = finiteNonNegative(direct.verificationPrefillOverlapSeconds), prefillWaitSeconds = finiteNonNegative(direct.verificationPrefillWaitSeconds);
    if (prefillAhead) verificationPrefillAheadPrompts += 1; verificationPrefillAheadSeconds += prefillAheadSeconds; verificationPrefillOverlapSeconds += prefillOverlapSeconds; verificationPrefillWaitSeconds += prefillWaitSeconds;
    const verificationCacheHit = direct.verificationSessionCacheHit === true, prefixReused = Number.isSafeInteger(direct.verificationPrefixTokensReused) && direct.verificationPrefixTokensReused >= 0 ? direct.verificationPrefixTokensReused : 0, prefillComputed = Number.isSafeInteger(direct.verificationPrefillTokensComputed) && direct.verificationPrefillTokensComputed >= 0 ? direct.verificationPrefillTokensComputed : 0;
    if (verificationCacheHit) verificationSessionCacheHitPrompts += 1; verificationPrefixTokensReused += prefixReused; verificationPrefillTokensComputed += prefillComputed;
    const firstToken = execution?.firstTokenWallSeconds ?? execution?.firstTokenForwardSeconds; if (typeof firstToken === "number" && Number.isFinite(firstToken) && firstToken >= 0) firstTokenSeconds.push(firstToken);
    const agreementSteps = Array.isArray(direct.logitAgreement?.steps) ? direct.logitAgreement.steps : [];
    for (const step of agreementSteps) if (step?.contextsEqualBeforeStep === true) { if (step.baselineArgmaxToken !== step.directArgmaxToken) directRootDivergences += 1; if (typeof step.topKOverlapRate === "number" && Number.isFinite(step.topKOverlapRate)) topKOverlapRates.push(step.topKOverlapRate); if (typeof step.baselineArgmaxLogitAbsError === "number" && Number.isFinite(step.baselineArgmaxLogitAbsError)) selectedLogitErrors.push(step.baselineArgmaxLogitAbsError); }
    let firstDivergentStep: number | null = null; for (let step = 0; step < Math.max(baseline.length, generated.length); step += 1) if (baseline[step] !== generated[step]) { firstDivergentStep = step; break; }
    cases.push({ prompt: report.prompt, tokensEqual, firstDivergentStep, baselineTokenIds: [...baseline], directTokenIds: [...generated], baselineSeconds: performance.baselineSeconds, directSeconds: direct.elapsedSeconds, speedup: direct.elapsedSeconds === 0 ? 0 : performance.baselineSeconds / direct.elapsedSeconds, firstTokenWallSeconds: typeof firstToken === "number" && Number.isFinite(firstToken) ? firstToken : null, selectedBackend: typeof direct.selectedBackend === "string" ? direct.selectedBackend : typeof direct.linearBackend === "string" ? direct.linearBackend : "unknown", fallbackTriggered: direct.fallbackTriggered === true, correctionTriggered: direct.fallbackChangedTokens === true || direct.controlCorrectionTriggered === true || Number.isSafeInteger(direct.verificationDivergenceStep), fallbackOutcome: typeof direct.fallbackOutcome === "string" ? direct.fallbackOutcome : null, verificationEarlyExitStep: earlyExitStep, verificationDecoderSteps: decoderSteps, verificationDecoderStepsAvoided: avoidedSteps, verificationHeadPositionsComputed: headPositionsComputed, verificationHeadPositionsAvoided: headPositionsAvoided, verificationPrefillAhead: prefillAhead, verificationPrefillAheadSeconds: prefillAheadSeconds, verificationPrefillOverlapSeconds: prefillOverlapSeconds, verificationPrefillWaitSeconds: prefillWaitSeconds, verificationSessionCacheHit: verificationCacheHit, verificationPrefixTokensReused: prefixReused, verificationPrefillTokensComputed: prefillComputed });
  }
  const mean = (values: number[]) => values.length === 0 ? null : values.reduce((sum, value) => sum + value, 0) / values.length, firstDivergentPrompt = cases.findIndex((entry) => !entry.tokensEqual);
  return { kind: "gemma4-ui-prompt-matrix", schemaVersion: 1, summary: { prompts: reports.length, promptsEqual, promptAgreementRate: promptsEqual / reports.length, comparedTokenSteps, equalTokenSteps, tokenAgreementRate: comparedTokenSteps === 0 ? 0 : equalTokenSteps / comparedTokenSteps, firstDivergentPrompt: firstDivergentPrompt < 0 ? null : firstDivergentPrompt, fallbackPrompts, fallbackRate: fallbackPrompts / reports.length, correctionPrompts, fallbackImprovedPrompts, fallbackWorsenedPrompts, fallbackChangedStillDivergentPrompts, verificationEarlyExitPrompts, verificationDecoderSteps, verificationDecoderStepsAvoided, verificationHeadPositionsComputed, verificationHeadPositionsAvoided, verificationPrefillAheadPrompts, verificationPrefillAheadSeconds, verificationPrefillOverlapSeconds, verificationPrefillWaitSeconds, verificationSessionCacheHitPrompts, verificationPrefixTokensReused, verificationPrefillTokensComputed, baselineSeconds, directSeconds, baselineTokensPerSecond: baselineSeconds === 0 ? 0 : comparedTokenSteps / baselineSeconds, directTokensPerSecond: directSeconds === 0 ? 0 : comparedTokenSteps / directSeconds, directVsBaselineThroughputRatio: directSeconds === 0 ? 0 : baselineSeconds / directSeconds, meanFirstTokenWallSeconds: mean(firstTokenSeconds), directRootDivergences, meanTopKOverlapRate: mean(topKOverlapRates), maxBaselineArgmaxLogitAbsError: selectedLogitErrors.length === 0 ? null : Math.max(...selectedLogitErrors) }, cases, reports: [...reports] };
}

function finiteNonNegative(value: unknown): number { return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0; }

export interface Gemma4PrimaryComparisonView {
  baselineText: string;
  compiledText: string;
  baselineTokenIds: number[];
  compiledTokenIds: number[];
  tokensEqual: boolean;
  firstDivergentStep: number | null;
  compatibility: { text: string; tokenIds: number[]; tokensEqual: boolean; firstDivergentStep: number | null; precision: string; roundingPolicy: string };
}

export function projectGemma4PrimaryComparison(value: unknown): Gemma4PrimaryComparisonView {
  if (typeof value !== "object" || value === null) throw new Error("Relatório original × compilado deve ser objeto.");
  const report = value as Record<string, any>, direct = report.direct;
  const baselineTokenIds = report.baselineGeneratedTokenIds, compiledTokenIds = direct?.generatedTokenIds, compatibilityTokenIds = report.candidateGeneratedTokenIds;
  if (typeof report.baselineGeneratedText !== "string" || typeof direct?.generatedText !== "string" || !Array.isArray(baselineTokenIds) || !Array.isArray(compiledTokenIds) || !Array.isArray(compatibilityTokenIds) || !baselineTokenIds.every(Number.isSafeInteger) || !compiledTokenIds.every(Number.isSafeInteger) || !compatibilityTokenIds.every(Number.isSafeInteger)) throw new Error("Relatório não contém as saídas original, compilada e de compatibilidade.");
  let firstDivergentStep: number | null = null;
  for (let step = 0; step < Math.max(baselineTokenIds.length, compiledTokenIds.length); step += 1) if (baselineTokenIds[step] !== compiledTokenIds[step]) { firstDivergentStep = step; break; }
  let compatibilityDivergence: number | null = null;
  for (let step = 0; step < Math.max(baselineTokenIds.length, compatibilityTokenIds.length); step += 1) if (baselineTokenIds[step] !== compatibilityTokenIds[step]) { compatibilityDivergence = step; break; }
  return {
    baselineText: report.baselineGeneratedText,
    compiledText: direct.generatedText,
    baselineTokenIds: [...baselineTokenIds],
    compiledTokenIds: [...compiledTokenIds],
    tokensEqual: firstDivergentStep === null,
    firstDivergentStep,
    compatibility: {
      text: typeof report.candidateGeneratedText === "string" ? report.candidateGeneratedText : "",
      tokenIds: [...compatibilityTokenIds],
      tokensEqual: compatibilityDivergence === null,
      firstDivergentStep: compatibilityDivergence,
      precision: typeof report.candidatePrecision === "string" ? report.candidatePrecision : "unknown",
      roundingPolicy: typeof report.roundingPolicy === "string" ? report.roundingPolicy : "unknown",
    },
  };
}

