const q = id => document.getElementById(id), run=q('run'), batchRun=q('batchRun'), downloadBatch=q('downloadBatch'), cancel=q('cancel'), mode=q('mode'), executionMode=q('executionMode'), inspectFormula=q('inspectFormula'); let sessionId=Math.floor(Math.random()*0xfffffffe)+1,hasSession=false,activeController,checkpointChatTemplateDeclared=false,lastBatchReport,prefillAheadActive=false;
