const resetConversation=message=>{activeController?.abort();sessionId=Math.floor(Math.random()*0xfffffffe)+1;hasSession=false;q('chat').replaceChildren();q('chat').hidden=true;clearComparison();q('prompt').value='';q('status').textContent=message;};
const renderFormula=(key,expression,evidence,resolved)=>{q('formulaPanel').hidden=false;q('formulaExample').textContent=key+'(x) = '+expression+(resolved?'\\n\\nRESOLUÇÃO EXATA NO SSA\\n'+JSON.stringify(resolved,null,2):'');q('formulaEvidence').textContent=evidence;};
async function initializeExecutors(){run.disabled=true;for(let attempt=0;attempt<480;attempt++){try{const response=await fetch('/api/status');const state=await response.json();if(state.error)throw new Error(state.error);checkpointChatTemplateDeclared=state.checkpointChatTemplateDeclared===true;updateModeNotice();const compiled=state.compiledProgram,realStack=state.direct?.fusedDecoderStackRounding==='real',lowering=state.direct?.vectorizedRealLowering,plan=compiled?.directRuntime?.plan,unit=compiled?.directRuntime?.compiledOutputProgram,finalProgram=state.direct?.finalFormulaProgram;q('compiledContract').textContent=compiled?'Fórmula global '+compiled.globalFormula.sha256.slice(0,12)+'… compilada como DAG paramétrico executável. O runtime rápido atual é '+compiled.directRuntime.engine+(realStack?', com decoder vetorizado sem arredondamentos BF16 intermediários e BF16 apenas na saída final':', com fronteiras BF16 internas')+(lowering&&plan&&unit?'; unidade '+unit.id+' executa em '+unit.logicalDispatchesPerForward+' despacho lógico, cobre '+lowering.source.globalClosureFunctions+' funções em '+Object.keys(lowering.coverage.kernels).length+' famílias Metal e produz '+plan.outputFunctions+' dimensões finais vinculadas ao SSA '+plan.standaloneSsaOutputsSha256.slice(0,12)+'…. O worker ordena o hot path pelo plano persistido '+plan.sha256.slice(0,12)+'… e exige que raízes finais, SSA e programa autenticado coincidam antes de gerar.':'; sem unidade executável e certificado concordantes publicados pelo worker.')+(compiled.finalFormulaMap?' Mapa '+compiled.finalFormulaMap.file+' contém '+compiled.finalFormulaMap.functions.toLocaleString('pt-BR')+' F_n(x), SHA-256 '+compiled.finalFormulaMap.sha256.slice(0,12)+'….':' Mapa final ausente.')+(compiled.finalFormulaRuntime?' EVAL_EXACT_DAG é definido por '+compiled.finalFormulaRuntime.file+' schema '+compiled.finalFormulaRuntime.schemaVersion+', SHA-256 '+compiled.finalFormulaRuntime.sha256.slice(0,12)+'….':' Runtime explícito de EVAL_EXACT_DAG ausente.')+(finalProgram?' O worker autenticou as '+finalProgram.functions.toLocaleString('pt-BR')+' raízes, o runtime '+finalProgram.runtimeContractSha256.slice(0,12)+'… e os executa pelo lowering vetorial compartilhado.':' O worker ainda não publicou o vínculo executável do mapa final.')+(compiled.runtimeIndex?' Índice de execução schema '+compiled.runtimeIndex.schemaVersion+' '+compiled.runtimeIndex.sha256.slice(0,12)+'… autenticado contra o constant pool.':' Índice de execução ausente; workers varrem o JSON literal completo.'):'Bundle sem contrato explícito da fórmula global.';const formula=compiled?.exampleFormula,terminal=compiled?.terminalLogitOutputs,map=compiled?.finalFormulaMap;if(formula&&terminal&&map){q('formulaDimension').max=String(terminal.dimensions-1);inspectFormula.disabled=false;renderFormula(formula.key,'BF16_RNE(EVAL_EXACT_DAG("'+formula.root+'", x))','única entrada variável: '+formula.inputTensor+'[0..'+(formula.inputLength-1)+'] · '+formula.expressionNodes.toLocaleString('pt-BR')+' nós em '+formula.file+' · '+map.functions.toLocaleString('pt-BR')+' funções em '+map.file+' · SHA-256 '+map.sha256+' · runtime '+compiled.finalFormulaRuntime.file+' '+compiled.finalFormulaRuntime.sha256);}if(!state.direct?.enabled){q('status').textContent='Executor direto ausente: gere ou informe o bundle compilado.';return;}if(state.ready){const verifier=state.direct?.verification;q('status').textContent='Pronto · tokenizer leve '+(state.tokenizer?.ready?'pronto':'indisponível')+' · referência '+(state.reference?.state==='unloaded'?'será carregada após a resposta compilada':state.reference?.state)+' · '+(state.direct?.sourceIndependentBundle?'bundle compilado autocontido':'pesos externos explícitos')+' · índice runtime '+(compiled?.runtimeIndex?'schema '+compiled.runtimeIndex.schemaVersion+' autenticado':'ausente')+' · checkpoint '+(checkpointChatTemplateDeclared?'com':'sem')+' template de chat · warm-up Metal '+(state.direct?.warmupSeconds??0).toFixed(2)+'s · verificador '+(verifier?.enabled===false?'desabilitado':verifier?.warmupComplete?'exato aquecido em '+(verifier.warmupSeconds??0).toFixed(2)+'s':verifier?.state==='unloaded'?'sob demanda':verifier?.ready?'pronto':'inicializando')+'.';run.disabled=false;return;}q('status').textContent=!state.direct?.warmupComplete?'Aquecendo o forward compilado no Metal…':'Aquecendo o verificador exato persistente…';}catch(error){q('status').textContent='Inicialização: '+error.message;}await new Promise(resolve=>setTimeout(resolve,500));}q('status').textContent='Inicialização excedeu 240s.';}
void initializeExecutors().then(()=>{batchRun.disabled=run.disabled;q('batchStatus').textContent=batchRun.disabled?'Runtime indisponível.':'Pronto para executar a matriz.';});
inspectFormula.addEventListener('click',async()=>{const dimension=Number(q('formulaDimension').value);inspectFormula.disabled=true;q('formulaEvidence').textContent='Resolvendo o binding, a raiz e o corpo da operação no SSA global…';try{const response=await fetch('/api/final-formula?dimension='+encodeURIComponent(dimension)),formula=await response.json();if(!response.ok)throw new Error(formula.error||'Falha ao carregar função final.');const body=formula.resolvedMath.operation?.bodyFragment;renderFormula(formula.key,formula.expression,'token '+formula.token.id+' = '+JSON.stringify(formula.token.text)+' · única entrada variável: '+formula.onlyFreeInput+' · '+formula.formulaMap.key+' em '+formula.formulaMap.file+' · mapa SHA-256 '+formula.formulaMap.sha256+' · EVAL_EXACT_DAG definido por '+formula.formulaRuntime.file+' '+formula.formulaRuntime.sha256+' · raiz '+formula.root+' resolvida em '+formula.resolvedMath.node.kind+(formula.resolvedMath.operation?' → '+formula.resolvedMath.operation.operationId+' → '+formula.resolvedMath.operation.bodyNode.kind:'')+(body?.truncated?' · fragmento limitado em chamadas de outras closures, todas identificadas pelo functionId no mesmo SSA':' · fragmento totalmente expandido')+' · outputBindings SHA-256 '+formula.outputBindingsSha256,formula.resolvedMath);}catch(error){q('formulaEvidence').textContent='Erro: '+error.message;}finally{inspectFormula.disabled=false;}});
cancel.addEventListener('click',()=>{activeController?.abort();cancel.disabled=true;});
